namespace Si_Eject
{
	public class Eject : MelonMod
	{
		public override void OnLateInitializeMelon()
		{
			HelperMethods.CommandCallback adminCallback = Command_Eject;
			HelperMethods.RegisterAdminCommand("eject", adminCallback, Power.Eject, "Ejects target player from their vehicle. Usage: !eject <player>");
		}

		public static void Command_Eject(Player? callerPlayer, string args)
		{
			string text = args.Split(' ')[0];
			int num = args.Split(' ').Length - 1;
			if (num > 1)
			{
				HelperMethods.SendChatMessageToPlayer(callerPlayer, "<b><color=#DDE98C>[</color><color=#DFA725>SAM</color><color=#DDE98C>]</color></b> ", text, ": Too many arguments");
				return;
			}
			if (num < 1)
			{
				HelperMethods.SendChatMessageToPlayer(callerPlayer, "<b><color=#DDE98C>[</color><color=#DFA725>SAM</color><color=#DDE98C>]</color></b> ", text, ": Too few arguments");
				return;
			}
			Player player = HelperMethods.FindTargetPlayer(args.Split(' ')[1]);
			if (player == null)
			{
				HelperMethods.SendChatMessageToPlayer(callerPlayer, "<b><color=#DDE98C>[</color><color=#DFA725>SAM</color><color=#DDE98C>]</color></b> ", text, ": Ambiguous or invalid target");
				return;
			}
			if (callerPlayer != null && !callerPlayer.CanAdminTarget(player))
			{
				HelperMethods.ReplyToCommand_Player(player, "is immune due to level");
				return;
			}
			Unit controlledUnit = player.ControlledUnit;
			if (controlledUnit == null)
			{
				HelperMethods.SendChatMessageToPlayer(callerPlayer, "<b><color=#DDE98C>[</color><color=#DFA725>SAM</color><color=#DDE98C>]</color></b> ", text, ": Player does not have a vehicle");
				return;
			}
			UnitCompartment driverCompartment = controlledUnit.DriverCompartment;
			if (driverCompartment == null)
			{
				HelperMethods.SendChatMessageToPlayer(callerPlayer, "<b><color=#DDE98C>[</color><color=#DFA725>SAM</color><color=#DDE98C>]</color></b> ", text, ": Player is not inside the vehicle");
			}
			else if (!driverCompartment.IsDriver)
			{
				HelperMethods.SendChatMessageToPlayer(callerPlayer, "<b><color=#DDE98C>[</color><color=#DFA725>SAM</color><color=#DDE98C>]</color></b> ", text, ": Player is not driving the vehicle");
			}
			else
			{
				Unit driverUnit = driverCompartment.DriverUnit;
				driverCompartment.RequestRemoveUnit(driverUnit);
				MelonLogger.Msg("Ejecting player (" + player.PlayerName + ") from vehicle: " + controlledUnit.ToString());
				HelperMethods.AlertAdminActivity(callerPlayer, player, "ejected");
			}
		}
	}
}
